# Tab completion for bxSites, for bash (and zsh, through bashcompinit).
# Generated by tools/generate-completions.bxs from the verb table in ModuleConfig.bx, do not edit.
# install-bx-module installs it from the "completions" setting in box.json. Without the installer, load it with:
#   source <module folder>/completions/bxSites.bash

# bash splits words on ":" too, so for "page:ne" it only replaces "ne": drop what comes before the last colon
_bxsites_trim_colon() {
	[[ "$COMP_WORDBREAKS" == *:* && "$1" == *:* ]] || return 0
	local prefix="${1%"${1##*:}"}" i
	for i in "${!COMPREPLY[@]}"; do
		COMPREPLY[i]="${COMPREPLY[i]#"$prefix"}"
	done
}

_bxsites_complete() {
	local line="${COMP_LINE:0:COMP_POINT}"
	local -a words
	read -ra words <<< "$line"
	if [[ "$line" =~ [[:space:]]$ ]]; then
		words+=("")
	fi
	local count=${#words[@]}
	local cur="${words[count-1]}"
	local verbs="agents:sync audit blog:drafts blog:find build clean coldbox deploy docbox doctor gh-deploy i18n:new i18n:status install:plugin install:theme lint migrate new package page:new page:rename plugin:new post:new publish search-index search:query serve skills:install stats theme:import theme:new version:new help"
	local globals="--help -h --version -v"
	COMPREPLY=()

	# bxSites <verb>
	if (( count <= 2 )); then
		if [[ "$cur" == -* ]]; then
			COMPREPLY=($(compgen -W "$globals" -- "$cur"))
		else
			COMPREPLY=($(compgen -W "$verbs" -- "$cur"))
			_bxsites_trim_colon "$cur"
		fi
		return 0
	fi

	# bxSites page <new|rename>: a colon verb written as two words
	if (( count == 3 )) && [[ " $verbs " != *" ${words[1]} "* ]]; then
		local seconds=""
		case "${words[1]}" in
			agents) seconds="sync" ;;
			blog) seconds="drafts find" ;;
			i18n) seconds="new status" ;;
			install) seconds="plugin theme" ;;
			page) seconds="new rename" ;;
			plugin) seconds="new" ;;
			post) seconds="new" ;;
			search) seconds="query" ;;
			skills) seconds="install" ;;
			theme) seconds="import new" ;;
			version) seconds="new" ;;
		esac
		if [[ -n "$seconds" && "$cur" != -* ]]; then
			COMPREPLY=($(compgen -W "$seconds" -- "$cur"))
			return 0
		fi
	fi

	local verb="${words[1]}"
	if (( count >= 4 )) && [[ " $verbs " == *" ${words[1]}:${words[2]} "* ]]; then
		verb="${words[1]}:${words[2]}"
	fi

	# --flag=<value>: bash replaces only what follows the "="
	if [[ "$cur" == --*=* ]]; then
		local flag="${cur%%=*}" part="${cur#*=}"
		case "$verb $flag" in
			"agents:sync --agents") COMPREPLY=($(compgen -W "agents none" -- "$part")) ;;
			"agents:sync --projectRoot") COMPREPLY=($(compgen -f -- "$part")); compopt -o filenames 2>/dev/null ;;
			"audit --projectRoot") COMPREPLY=($(compgen -f -- "$part")); compopt -o filenames 2>/dev/null ;;
			"blog:drafts --projectRoot") COMPREPLY=($(compgen -f -- "$part")); compopt -o filenames 2>/dev/null ;;
			"blog:find --projectRoot") COMPREPLY=($(compgen -f -- "$part")); compopt -o filenames 2>/dev/null ;;
			"build --projectRoot") COMPREPLY=($(compgen -f -- "$part")); compopt -o filenames 2>/dev/null ;;
			"clean --projectRoot") COMPREPLY=($(compgen -f -- "$part")); compopt -o filenames 2>/dev/null ;;
			"coldbox --appRoot") COMPREPLY=($(compgen -f -- "$part")); compopt -o filenames 2>/dev/null ;;
			"coldbox --projectRoot") COMPREPLY=($(compgen -f -- "$part")); compopt -o filenames 2>/dev/null ;;
			"deploy --target") COMPREPLY=($(compgen -W "s3 azure gcs firebase ftp sftp rsync netlify vercel cloudflare-pages local github-pages" -- "$part")) ;;
			"deploy --projectRoot") COMPREPLY=($(compgen -f -- "$part")); compopt -o filenames 2>/dev/null ;;
			"docbox --jsonDir") COMPREPLY=($(compgen -f -- "$part")); compopt -o filenames 2>/dev/null ;;
			"docbox --projectRoot") COMPREPLY=($(compgen -f -- "$part")); compopt -o filenames 2>/dev/null ;;
			"doctor --projectRoot") COMPREPLY=($(compgen -f -- "$part")); compopt -o filenames 2>/dev/null ;;
			"gh-deploy --projectRoot") COMPREPLY=($(compgen -f -- "$part")); compopt -o filenames 2>/dev/null ;;
			"i18n:new --projectRoot") COMPREPLY=($(compgen -f -- "$part")); compopt -o filenames 2>/dev/null ;;
			"i18n:status --projectRoot") COMPREPLY=($(compgen -f -- "$part")); compopt -o filenames 2>/dev/null ;;
			"install:plugin --projectRoot") COMPREPLY=($(compgen -f -- "$part")); compopt -o filenames 2>/dev/null ;;
			"install:theme --projectRoot") COMPREPLY=($(compgen -f -- "$part")); compopt -o filenames 2>/dev/null ;;
			"lint --projectRoot") COMPREPLY=($(compgen -f -- "$part")); compopt -o filenames 2>/dev/null ;;
			"migrate --source") COMPREPLY=($(compgen -f -- "$part")); compopt -o filenames 2>/dev/null ;;
			"migrate --from") COMPREPLY=($(compgen -W "gitbook mkdocs markdown-zip notion" -- "$part")) ;;
			"migrate --projectRoot") COMPREPLY=($(compgen -f -- "$part")); compopt -o filenames 2>/dev/null ;;
			"new --theme") COMPREPLY=($(compgen -W "bootstrap docsy docusaurus gitbook justthedocs material notion slate tailwind vuepress" -- "$part")) ;;
			"new --source") COMPREPLY=($(compgen -W "docs src" -- "$part")) ;;
			"new --agents") COMPREPLY=($(compgen -W "agents none" -- "$part")) ;;
			"new --format") COMPREPLY=($(compgen -W "yaml toml json" -- "$part")) ;;
			"new --projectRoot") COMPREPLY=($(compgen -f -- "$part")); compopt -o filenames 2>/dev/null ;;
			"package --output") COMPREPLY=($(compgen -f -- "$part")); compopt -o filenames 2>/dev/null ;;
			"package --projectRoot") COMPREPLY=($(compgen -f -- "$part")); compopt -o filenames 2>/dev/null ;;
			"page:new --path") COMPREPLY=($(compgen -f -- "$part")); compopt -o filenames 2>/dev/null ;;
			"page:new --projectRoot") COMPREPLY=($(compgen -f -- "$part")); compopt -o filenames 2>/dev/null ;;
			"page:rename --from") COMPREPLY=($(compgen -f -- "$part")); compopt -o filenames 2>/dev/null ;;
			"page:rename --to") COMPREPLY=($(compgen -f -- "$part")); compopt -o filenames 2>/dev/null ;;
			"page:rename --projectRoot") COMPREPLY=($(compgen -f -- "$part")); compopt -o filenames 2>/dev/null ;;
			"plugin:new --dest") COMPREPLY=($(compgen -f -- "$part")); compopt -o filenames 2>/dev/null ;;
			"plugin:new --projectRoot") COMPREPLY=($(compgen -f -- "$part")); compopt -o filenames 2>/dev/null ;;
			"post:new --projectRoot") COMPREPLY=($(compgen -f -- "$part")); compopt -o filenames 2>/dev/null ;;
			"publish --projectRoot") COMPREPLY=($(compgen -f -- "$part")); compopt -o filenames 2>/dev/null ;;
			"search-index --projectRoot") COMPREPLY=($(compgen -f -- "$part")); compopt -o filenames 2>/dev/null ;;
			"search:query --projectRoot") COMPREPLY=($(compgen -f -- "$part")); compopt -o filenames 2>/dev/null ;;
			"serve --projectRoot") COMPREPLY=($(compgen -f -- "$part")); compopt -o filenames 2>/dev/null ;;
			"skills:install --projectRoot") COMPREPLY=($(compgen -f -- "$part")); compopt -o filenames 2>/dev/null ;;
			"stats --projectRoot") COMPREPLY=($(compgen -f -- "$part")); compopt -o filenames 2>/dev/null ;;
			"theme:import --source") COMPREPLY=($(compgen -f -- "$part")); compopt -o filenames 2>/dev/null ;;
			"theme:import --path") COMPREPLY=($(compgen -f -- "$part")); compopt -o filenames 2>/dev/null ;;
			"theme:import --projectRoot") COMPREPLY=($(compgen -f -- "$part")); compopt -o filenames 2>/dev/null ;;
			"theme:new --theme") COMPREPLY=($(compgen -W "bootstrap docsy docusaurus gitbook justthedocs material notion slate tailwind vuepress" -- "$part")) ;;
			"theme:new --projectRoot") COMPREPLY=($(compgen -f -- "$part")); compopt -o filenames 2>/dev/null ;;
			"version:new --projectRoot") COMPREPLY=($(compgen -f -- "$part")); compopt -o filenames 2>/dev/null ;;
		esac
		return 0
	fi

	if [[ "$cur" == -* ]]; then
		local flags=""
		case "$verb" in
			agents:sync) flags="--agents= --projectRoot=" ;;
			audit) flags="--projectRoot=" ;;
			blog:drafts) flags="--projectRoot=" ;;
			blog:find) flags="--author= --category= --tag= --since= --until= --drafts --projectRoot=" ;;
			build) flags="--projectRoot=" ;;
			clean) flags="--force --projectRoot=" ;;
			coldbox) flags="--appRoot= --pagePathPrefix= --tags= --include= --projectRoot=" ;;
			deploy) flags="--entry= --target= --verbose --projectRoot=" ;;
			docbox) flags="--mappings: --projectTitle= --excludes= --pagePathPrefix= --tags= --jsonDir= --projectRoot=" ;;
			doctor) flags="--projectRoot=" ;;
			gh-deploy) flags="--branch= --remote= --message= --projectRoot=" ;;
			i18n:new) flags="--code= --projectRoot=" ;;
			i18n:status) flags="--projectRoot=" ;;
			install:plugin) flags="--name= --version= --projectRoot=" ;;
			install:theme) flags="--name= --version= --projectRoot=" ;;
			lint) flags="--projectRoot=" ;;
			migrate) flags="--source= --from= --force --projectRoot=" ;;
			new) flags="--theme= --name= --source= --docs --site --agents= --description= --format= --no-agents --projectRoot=" ;;
			package) flags="--output= --projectRoot=" ;;
			page:new) flags="--path= --title= --description= --icon= --tags= --order= --projectRoot=" ;;
			page:rename) flags="--from= --to= --projectRoot=" ;;
			plugin:new) flags="--name= --dest= --projectRoot=" ;;
			post:new) flags="--title= --slug= --date= --authors= --categories= --tags= --draft --projectRoot=" ;;
			publish) flags="--token= --projectRoot=" ;;
			search-index) flags="--projectRoot=" ;;
			search:query) flags="--query= --limit= --projectRoot=" ;;
			serve) flags="--port= --host= --projectRoot=" ;;
			skills:install) flags="--skill= --projectRoot=" ;;
			stats) flags="--projectRoot=" ;;
			theme:import) flags="--source= --path= --name= --force --projectRoot=" ;;
			theme:new) flags="--theme= --projectRoot=" ;;
			version:new) flags="--name= --projectRoot=" ;;
		esac
		COMPREPLY=($(compgen -W "$flags $globals" -- "$cur"))
		if (( ${#COMPREPLY[@]} == 1 )) && [[ "${COMPREPLY[0]}" == *[=:] ]]; then
			compopt -o nospace 2>/dev/null
		fi
		return 0
	fi

	case "$verb" in
		new) COMPREPLY=($(compgen -d -- "$cur")); compopt -o filenames 2>/dev/null ;;
		help) COMPREPLY=($(compgen -W "$verbs" -- "$cur")); _bxsites_trim_colon "$cur" ;;
	esac
	return 0
}

complete -F _bxsites_complete bxSites bxsites
